const mealCard=(m,i)=>`<article class="card"><div class="image-wrap"><img class="recipe-photo" src="${foodAssets+m.image}" alt="${m.name}"><div class="float-label"><span>${m.tag}</span><span>${m.time}</span></div></div><div class="card-body"><h3>${m.name}</h3><div class="ingredient-meter" aria-hidden="true">${m.ingredients.map(x=>`<span class="${pantry.has(x)?'have':''}"></span>`).join('')}</div><p class="meta">${m.ingredients.length-missing(m).length} of ${m.ingredients.length} listed ingredients in your pantry</p><div class="actions">${B('View recipe '+I('arrow'),'meal:'+i,true)}<button class="icon-button" data-action="plan:${m.id}" aria-label="${plan.has(m.id)?'Remove':'Add'} ${m.name} ${plan.has(m.id)?'from':'to'} plan" aria-pressed="${plan.has(m.id)}">${I(plan.has(m.id)?'check':'plus')}</button></div></div></article>`;
function nutriva(){const m=meals[mealIndex];if(view==='recipe')return `${back('view:tonight','Tonight’s ideas')}<div class="recipe-detail"><img src="${foodAssets+m.image}" alt="${m.name}"><section><p class="eyebrow">${m.tag}</p><h1>${m.name}</h1><p class="sub">${m.desc}</p><div class="tour-meta"><span>${I('clock')}${m.time}</span><span>${I('leaf')}Illustrative recipe</span></div><h2 style="font-size:28px;margin-top:28px">A short shopping story.</h2>${m.ingredients.map(i=>`<div class="ingredient-line"><strong>${i}</strong><span>${pantry.has(i)?I('check')+' In pantry':pill('Add to groceries')}</span></div>`).join('')}<div class="actions">${B(plan.has(m.id)?'✓ Planned · Remove':'Add to this week '+I('plus'),'plan:'+m.id,plan.has(m.id))}${B('Review pantry','view:pantry',true)}</div><div class="notice">An interface study with illustrative recipe information. A complete recipe would include verified quantities and preparation instructions.</div></section></div>`;
if(view==='pantry')return `${title('Your kitchen / Pantry','A useful place<br>to <em>begin.</em>','Keep your pantry current. Your meal matches and grocery list update together.')}<div class="two-col"><section class="panel"><div class="toolbar" style="margin:0"><h2>Already at home</h2><span class="pantry-count">${pantry.size.toString().padStart(2,'0')}</span></div>${[...pantry].map(i=>`<div class="pantry-item"><span class="food-initial">${i[0]}</span><div><strong>${i}</strong><small>Available in sample pantry</small></div><button class="button quiet" data-action="remove-ingredient:${E(i)}" aria-label="Remove ${E(i)}">Remove</button></div>`).join('')||'<p class="sub">Your pantry is empty. Add an ingredient to begin.</p>'}</section><form class="panel" id="pantry-form"><p class="eyebrow">A small update, a better plan</p><h2>Add to your pantry.</h2><label class="field">Ingredient<select name="ingredient">${['Lentils','Tomatoes','Pasta','Olive oil','Carrots','Salmon','Lemon'].map(i=>`<option>${i}</option>`).join('')}</select></label><button class="button" type="submit">Add ingredient ${I('plus')}</button><p class="sub">Duplicate ingredients are caught before they are added.</p></form></div>`;
if(view==='grocery'){const g=grocery();return `${title('Your kitchen / Grocery list','Just what<br>you’re <em>missing.</em>','Ingredients from your planned meals, with pantry items and duplicates removed.')}<div class="two-col"><section class="panel"><div class="toolbar" style="margin:0 0 15px"><h2>Your list</h2>${pill(g.length+' ingredients')}</div>${g.length?g.map(i=>`<label class="grocery-label"><input type="checkbox" data-grocery="${i}" ${checked.has(i)?'checked':''}><span>${i}</span></label>`).join(''):`<p class="sub">${plan.size?'You have all listed ingredients for your planned sample meals.':'Plan a meal to create your grocery list.'}</p>`}</section><aside class="panel"><p class="eyebrow">Connected to your week</p><h2>${plan.size} meals in the plan.</h2><p class="sub">Change a meal or update the pantry and this list changes with it.</p><div class="actions">${B('Review this week','view:plan',true)}</div></aside></div>`;}
if(view==='plan'){const selected=meals.filter(m=>plan.has(m.id));return `${title('Your kitchen / This week','A little structure.<br><em>Room to change.</em>','Choose the meals you want, then make the week your own.')}<div class="toolbar"><span class="meta">${selected.length} planned meals</span>${B('Grocery list '+I('arrow'),'view:grocery',true)}</div>${selected.length?`<div class="week-grid">${selected.map((m,i)=>`<article class="day-card"><div class="day-label">Meal 0${i+1} <span class="meta">/ Your choice of day</span></div><img src="${foodAssets+m.image}" alt="${m.name}"><div class="card-body"><h3>${m.name}</h3><p class="meta" style="margin-top:12px">${m.time} · ${missing(m).length} ingredients to add</p><div class="actions">${B('Remove from plan','plan:'+m.id,true)}</div></div></article>`).join('')}</div>`:empty('Start with one good meal.','Find something you’d enjoy and add it to your flexible weekly plan.','view:tonight','Find a meal '+I('arrow'))}`;}
return `<div class="hero-card meal-hero"><div class="hero-copy"><p class="eyebrow">Your everyday kitchen</p><h1>Good food.<br>Less <em>figuring out.</em></h1><p class="sub">A few thoughtful ideas, starting with what you already have.</p><div class="actions">${B('What’s in my pantry?','view:pantry')}</div></div><img class="hero-image" src="${foodAssets}lemon-herb-salmon.webp" alt="Lemon herb salmon with fresh vegetables"></div><div class="section-title"><div><p class="eyebrow">A little inspiration for tonight</p><h2>From your pantry, with possibility.</h2></div>${pill(pantry.size+' pantry ingredients')}</div><div class="grid">${meals.map(mealCard).join('')}</div>`;}

// NOVELLA — mood discovery, original book studies, collection and adjustable reader.
const books=[{title:'The Light Between Streets',mood:'reflective',line:'A quiet city. An unexpected return.',text:'On the first morning, the street looked smaller than she remembered. The bakery still opened before sunrise, and the windows above it still caught the light before anything else. She stood for a moment without deciding where to go. After so many years of making plans, the absence of one felt almost like an invitation.'},{title:'A House for the Summer',mood:'comforting',line:'Old friends. Open windows. A slower season.',text:'The house had been waiting with its windows open. Somewhere beyond the kitchen, someone was laughing, and the smell of toast drifted into the hall. She put down her bag and listened. Nothing extraordinary had happened yet. For once, she hoped that nothing would.'},{title:'The Last Observatory',mood:'mysterious',line:'One final signal from a silent mountain.',text:'At eleven minutes past midnight, the observatory received a signal. Its instruments had been disconnected for seven years. Mara read the numbers again, then checked the cable beneath the desk. The loose end lay exactly where she had left it. Outside, above the mountain, one unfamiliar point of light moved against the stars.'}];
let mood='all',savedBooks=new Set(demo?[0,2]:[]),bookIndex=Math.max(0,Math.min(2,Number(params.get('item'))||0)),night=false,readingSize=23;
const bookVisual=(b,i)=>`<div class="book-visual"><img src="${assets+bookImages[i]}" alt="${b.title} — original Novella cover artwork"></div>`;
const bookCard=(b,i)=>`<article class="shelf-card">${bookVisual(b,i)}<p class="eyebrow">${b.mood} / Original fiction study</p><h3>${b.title}</h3><p class="meta">${b.line}</p><div class="actions">${B('Explore this story','book:'+i,true)}<button class="icon-button" data-action="save-book:${i}" aria-pressed="${savedBooks.has(i)}" aria-label="${savedBooks.has(i)?'Unsave':'Save'} ${b.title}">${I(savedBooks.has(i)?'check':'save')}</button></div></article>`;
function novella(){const b=books[bookIndex];if(view==='book')return `${back('view:discover','The reading edit')}<div class="book-detail">${bookVisual(b,bookIndex)}<section><p class="eyebrow">${b.mood} / Novella original</p><h1>${b.title}</h1><p class="sub">${b.line}</p><p class="quote">“${b.text.split('. ')[0]}.”</p><div class="book-details">${pill('Original excerpt')} ${pill('Adjustable reading view')}</div><div class="actions">${B('Read a sample '+I('arrow'),'view:reader')}${B(savedBooks.has(bookIndex)?'Saved · Remove':'Save to my library','save-book:'+bookIndex,true)}</div><p class="meta" style="margin-top:25px">A fictional title and original excerpt created for this interface study.</p></section></div>`;
if(view==='reader')return `<div class="reader-tools">${back('book:'+bookIndex,'Book details')}<div class="actions">${B('A−','text-smaller',true,'aria-label="Decrease reading text size" '+(readingSize<=18?'disabled':''))}${B('A+','text-larger',true,'aria-label="Increase reading text size" '+(readingSize>=30?'disabled':''))}${B(night?'Light page':'Dark page','night',true,'aria-pressed="'+night+'"')}</div></div><article class="reading-sheet ${night?'night':''}" style="--reading-size:${readingSize}px"><p class="eyebrow">Novella original / Opening passage</p><h1>${b.title}</h1><p class="prose">${b.text}</p><p class="end-mark" aria-hidden="true">✳</p><p class="meta">End of this original sample. A full book is not available.</p></article>`;
const list=books.map((b,i)=>({b,i})).filter(({b,i})=>view==='library'?savedBooks.has(i):mood==='all'||b.mood===mood);
return `${view==='library'?title('Your library / A considered collection','The stories<br>you <em>keep.</em>','Return to what caught your attention. Your shelf stays here during this visit.'):`<div class="library-hero"><div><p class="eyebrow">A place for your next story</p><h1>What would you<br>like to <em>feel?</em></h1><p class="sub">Follow a mood. Linger over a sentence.<br>Find a story that meets you here.</p></div><img src="${assets}novella-campaign.webp" alt="Art-directed Novella fiction collection"></div><div class="toolbar"><div class="chips" role="group" aria-label="Reading mood">${['all','reflective','comforting','mysterious'].map(m=>`<button class="chip" data-action="mood:${m}" aria-pressed="${mood===m}">${m==='all'?'An open mind':m[0].toUpperCase()+m.slice(1)}</button>`).join('')}</div><span class="meta">${list.length} stories</span></div>`}${list.length?`<div class="grid">${list.map(({b,i})=>bookCard(b,i)).join('')}</div>`:empty('A shelf waiting for a story.','Save a title from discovery to begin your collection.','view:discover','Find your first story')}`;}

// ÁUREA — discovery, preference matching, note detail, comparison and wear journal.
const scents=[{name:'Vesper Rose',family:'floral',tag:'Soft floral',notes:['Pink pepper, bergamot','Rose petals, peony','White musk, pale woods'],mood:'Soft, romantic, quietly expressive.',description:'A peppery opening, a gentle floral heart, and a quiet musky finish.'},{name:'Sol Mist',family:'fresh',tag:'Fresh & bright',notes:['Bergamot, mandarin','Neroli, green tea','Soft cedar, clean musk'],mood:'Luminous, airy, easygoing.',description:'Brightness and green notes, held together by a light woody finish.'},{name:'Santal Dusk',family:'woody',tag:'Warm woods',notes:['Cardamom, black pepper','Iris, violet leaf','Sandalwood, amber'],mood:'Warm, textured, contemplative.',description:'Dry spice, powdery iris, and a warm, softly textured base.'}];
let scentIndex=Math.max(0,Math.min(2,Number(params.get('item'))||0)),family='all',query='',savedScents=new Set(demo?[0,2]:[]),compared=new Set(demo?[0,2]:[]),preference='floral',journal=[];
const scentCard=(s,i)=>`<article class="card scent-card"><div class="image-wrap"><img src="${assets+scentImages[i]}" alt="${s.name} — original fragrance concept artwork"><button class="icon-button" data-action="save-scent:${i}" aria-pressed="${savedScents.has(i)}" aria-label="${savedScents.has(i)?'Unsave':'Save'} ${s.name}">${I(savedScents.has(i)?'check':'save')}</button>${pill(s.tag)}</div><div class="card-body"><h3>${s.name}</h3><p class="meta">${s.notes[1]}</p><div class="actions">${B('Discover the notes','scent:'+i,true)}<button class="button quiet" data-action="compare:${i}" aria-pressed="${compared.has(i)}">${compared.has(i)?'✓ Selected':'+ Compare'}</button></div></div></article>`;
function aurea(){const s=scents[scentIndex];if(view==='detail')return `${back('view:discover','The scent edit')}<div class="scent-detail"><img src="${assets+scentImages[scentIndex]}" alt="${s.name} fragrance concept artwork"><section><p class="eyebrow">${s.tag} / An imagined composition</p><h1>${s.name}</h1><p class="sub">${s.description}</p><div class="notes">${s.notes.map((n,i)=>`<div class="note"><span class="number">0${i+1}</span><div><small>${['THE OPENING','THE HEART','THE BASE'][i]}</small><strong>${n}</strong></div></div>`).join('')}</div><div class="actions">${B(savedScents.has(scentIndex)?'Saved · Remove':'Save to my archive','save-scent:'+scentIndex)}${B(compared.has(scentIndex)?'✓ In comparison':'+ Compare','compare:'+scentIndex,true)}</div><p class="meta" style="margin-top:25px">Illustrative scent profile. No wear-time or performance claims.</p></section></div>`;
if(view==='finder')return `<div class="finder">${title('A more personal discovery / Scent finder','Begin with<br><em>a feeling.</em>','Choose the character that draws you in. Your selection shapes a transparent, illustrative recommendation.')}<div class="finder-options" role="group" aria-label="Preferred scent character">${[['floral','Soft & romantic','Petals, gentle musk, a little warmth.'],['fresh','Bright & easy','Citrus, green notes, open air.'],['woody','Warm & quiet','Dry spice, soft woods, texture.']].map(([v,n,d])=>`<button class="finder-option" data-action="preference:${v}" aria-pressed="${preference===v}">${I(preference===v?'check':'discover')}<b>${n}</b><small>${d}</small></button>`).join('')}</div>${B('Find a starting point '+I('arrow'),'view:results')}<p class="meta" style="margin-top:20px">A preference-based match, not a prediction of how a fragrance will wear.</p></div>`;
if(view==='results'){const i=scents.findIndex(s=>s.family===preference);return `${back('view:finder','Refine your feeling')}<div class="two-col"><section>${title('Your starting point / Why this match','A little more<br><em>like your mood.</em>',scents[i].mood)}<div class="panel"><p class="eyebrow">Your selection, explained</p><h2>${scents[i].tag}</h2><p class="sub">You chose a ${preference==='floral'?'soft, romantic':preference==='fresh'?'bright, easy':'warm, quiet'} character. ${scents[i].name} is the corresponding composition in this three-scent study.</p><div class="actions">${B('Explore another direction','view:finder',true)}</div></div></section>${scentCard(scents[i],i)}</div>`;}
if(view==='compare')return `${title('The details, side by side','A clearer<br><em>kind of choice.</em>','Compare character and notes, without a made-up performance score.')} ${compared.size===2?`<div class="comparison-grid">${[...compared].map(i=>`<article class="panel"><div class="compare-head"><img src="${assets+scentImages[i]}" alt="${scents[i].name} fragrance concept artwork"><div>${pill(scents[i].tag)}<h2 style="margin-top:12px">${scents[i].name}</h2></div></div><div class="row"><div><strong>Character</strong><p>${scents[i].mood}</p></div></div>${scents[i].notes.map((n,j)=>`<div class="row"><div><strong>${['Opening','Heart','Base'][j]}</strong><p>${n}</p></div></div>`).join('')}<div class="actions">${B('Remove','compare:'+i,true)}</div></article>`).join('')}</div>`:empty(compared.size?'One more perspective.':'A little perspective helps.',compared.size?'One fragrance is selected. Choose one more from the collection.':'Choose two fragrances to compare their notes side by side.','view:discover','Choose fragrances')}`;
if(view==='archive')return `${title('Your personal edit / Archive','Keep what<br><em>stays with you.</em>','The fragrances that caught your attention, and a place for your own impressions.')}<div class="toolbar"><span class="meta">${savedScents.size} saved fragrances</span>${B('Add a wear note '+I('plus'),'view:journal',true)}</div>${savedScents.size?`<div class="grid">${[...savedScents].map(i=>scentCard(scents[i],i)).join('')}</div>`:empty('The beginning of your archive.','Save a fragrance from the collection to keep it here.','view:discover','Discover a fragrance')}<div class="journal-list">${journal.map(j=>`<article class="journal-entry"><p class="eyebrow">Your wear note / This visit</p><h3>${scents[j.scent].name}</h3><p>${E(j.text)}</p></article>`).join('')}</div>`;
if(view==='journal')return `${back('view:archive','My archive')}<div class="two-col"><section>${title('A personal observation / Wear journal','How did it<br><em>stay with you?</em>','A simple place to describe your own impression.')}<p class="meta">Notes stay in this visit only. Nothing is uploaded or sent.</p></section><form class="panel" id="journal-form"><label class="field">Fragrance<select name="scent">${scents.map((s,i)=>`<option value="${i}">${s.name}</option>`).join('')}</select></label><label class="field">Your impression<textarea name="note" maxlength="600" placeholder="The opening, the mood, the little details…" required></textarea></label><p class="error" id="journal-error" role="alert"></p><button class="button" type="submit">Save wear note ${I('save')}</button></form></div>`;
const list=scents.map((s,i)=>({s,i})).filter(({s})=>(family==='all'||s.family===family)&&[s.name,s.tag,...s.notes].join(' ').toLowerCase().includes(query));
return `<div class="hero-card scent-hero"><div class="hero-copy"><p class="eyebrow">The olfactory archive / Volume 01</p><h1>A feeling.<br>A fragrance.<br><em>A little of you.</em></h1><div class="actions">${B('Find your starting point '+I('arrow'),'view:finder')}</div></div><img class="hero-image" src="${assets}aurea-editorial.webp" alt="Warm amber fragrance and a burgundy rose in afternoon light"></div><div class="toolbar"><h2>The curated edit.</h2><label class="search">${I('search')}<input type="search" id="scent-search" aria-label="Find a fragrance or note" placeholder="Rose, citrus, sandalwood…" value="${E(query)}"></label></div><div class="toolbar"><div class="chips" role="group" aria-label="Scent family">${[['all','All fragrances'],['floral','Soft florals'],['fresh','Fresh & bright'],['woody','Warm woods']].map(([v,n])=>`<button class="chip" data-action="family:${v}" aria-pressed="${family===v}">${n}</button>`).join('')}</div><span class="meta" role="status">${list.length} fragrances</span></div><div id="scent-results">${list.length?`<div class="grid">${list.map(({s,i})=>scentCard(s,i)).join('')}</div>`:empty('A different starting point.','No fragrances match. Try a different note or clear the filters.','clear-scents','Clear search & filters')}</div>${compared.size?`<div class="compare-tray"><span>${compared.size} of 2 selected for comparison</span>${B('Compare '+I('arrow'),'view:compare')}</div>`:''}`;}

