function purposeAction(a,v){
 if(a==='start-blind'){blindRevealed=false;view='blind';return true;}
 if(a==='reveal-book'){blindRevealed=true;return true;}
 if(a==='next-blind'){bookIndex=(bookIndex+1)%books.length;blindRevealed=false;return true;}
 if(a==='keep-passage'){if(!passages.includes(bookIndex))passages.push(bookIndex);say('Opening passage saved with its book title.');return true;}
 if(a==='remove-passage'){passages=passages.filter(i=>i!==Number(v));say('Passage removed.');return true;}
 if(a==='verify-success'&&sessionOpen){attendanceAudit.push({student:0,from:roster[0],to:'Present',by:'Student check-in'});roster[0]='Present';view='student';say('Sample check-in confirmed. No location collected.');return true;}
 return false;
}

