let noteFilter='',catalogLayout='cards',catalogSort='edit',walkStarted=demo&&['walk','story','complete','tools'].includes(view);
const noteName=n=>n.trim().charAt(0).toUpperCase()+n.trim().slice(1);
const noteList=s=>s.notes.flatMap(n=>n.split(',').map(noteName));
