const filteredPerfumes=()=>scents.map((s,i)=>({s,i})).filter(({s})=>(family==='all'||s.family===family)&&(!noteFilter||noteList(s).includes(noteFilter))&&[s.name,s.family,s.tag,...s.notes].join(' ').toLowerCase().includes(query)).sort((a,b)=>catalogSort==='az'?a.s.name.localeCompare(b.s.name):a.i-b.i);
function indexCard(s,i){return `<article class="au-index-card"><button class="au-photo-link" data-action="scent:${i}" aria-label="Open ${s.name}"><img src="${assets+scentImages[i]}" alt="${s.name} concept fragrance"><span class="au-record-number">A—00${i+1}</span></button><div class="au-card-copy"><div class="au-card-kicker"><span>${s.tag}</span><button class="icon-button" data-action="save-scent:${i}" aria-pressed="${savedScents.has(i)}" aria-label="${savedScents.has(i)?'Remove':'Save'} ${s.name}">${I(savedScents.has(i)?'check':'save')}</button></div><h2><button data-action="scent:${i}">${s.name}</button></h2><p>${s.description}</p><div class="au-note-chips">${noteList(s).slice(0,3).map(n=>`<button data-action="note-filter:${E(n)}">${n}</button>`).join('')}</div><div class="au-card-bottom">${B('View record','scent:'+i,true)}<button class="au-text-button" data-action="compare:${i}" aria-pressed="${compared.has(i)}">${compared.has(i)?'✓ Selected':'+ Compare'}</button></div></div></article>`;}
function compareDock(){return compared.size?`<aside class="au-compare-dock" aria-label="Your comparison"><div><strong>${compared.size} of 2 selected</strong><span>${[...compared].map(i=>scents[i].name).join(' · ')}</span></div><div class="actions">${B('Clear','clear-compare',true)}${B(compared.size===2?'Compare perfumes':'Choose one more',compared.size===2?'view:compare':'view:discover')}</div></aside>`:'';}
