function refinedAction(a,v){
 if(a==='note-filter'){noteFilter=noteName(v);family='all';query='';view='discover';return true;}
 if(a==='catalog-layout'){catalogLayout=v;return true;}
 if(a==='clear-compare'){compared.clear();return true;}
 if(a==='clear-scents'){noteFilter='';family='all';query='';return true;}
 if(a==='large-text'){hwTools.largeText=!hwTools.largeText;say(hwTools.largeText?'Larger text is on.':'Standard text is on.');return true;}
 if(a==='previous-stop'){if(!paused)walkStep=Math.max(0,walkStep-1);return true;}
 if(a==='start-walk')walkStarted=true;
 return false;
}


