  return (comparisonCandidate!==null?comparisonChoice():'')+original.replace(/<div class="au-active-filters">[\s\S]*?<\/div>/,`<div class="au-active-filters" role="group" aria-label="Remove one active filter">${chips}${B('Clear all','clear-scents',true)}</div>`);
