function comparisonChoice(){return `<section class="comparison-choice" role="region" aria-labelledby="comparison-choice-title"><p class="eyebrow">YOUR SHORTLIST IS FULL</p><h2 id="comparison-choice-title">Make room for ${scents[comparisonCandidate].name}?</h2><p>Choose which perfume to replace. The other selection stays in place.</p><div class="actions">${[...compared].map(i=>B('Replace '+scents[i].name,'replace-comparison:'+i,true)).join('')}${B('Keep my current pair','cancel-comparison',true)}</div></section>`;}
function depthAction(a,v){
 if(app==='imhere'&&(a==='approve'||a==='absent')){correction={student:Number(v),to:a==='approve'?'Present':'Absent'};view='correction';return true;}
 if(a==='cancel-correction'){correction=null;view='reviews';return true;}
 if(a==='edit-handoff'&&record){food=record.food;quantity=record.quantity;windowChoice=record.windowChoice;formStep=1;handoffEditing=true;view='create';return true;}
 if(a==='cancel-handoff-edit'){handoffEditing=false;view='confirmed';return true;}
 if(a==='new-handoff')handoffEditing=false;
 if(a==='remove-ingredient'){removedIngredient=v;pantry.delete(v);say(v+' removed. Undo is available.');return true;}
 if(a==='undo-ingredient'){if(removedIngredient)pantry.add(removedIngredient);removedIngredient='';say('Ingredient restored. Meal matches and groceries updated.');return true;}
 if(a==='set-shelf'){savedBooks.add(bookIndex);bookShelves[bookIndex]=v;say('Book saved to '+({want:'Want to read',reading:'Reading',finished:'Finished'}[v])+'.');return true;}
 if(a==='remove-passage'){removedPassage=Number(v);passages=passages.filter(i=>i!==removedPassage);say('Passage removed. Undo is available.');return true;}
 if(a==='undo-passage'){if(removedPassage!==null&&!passages.includes(removedPassage))passages.push(removedPassage);removedPassage=null;say('Passage restored with its source.');return true;}
 if(a==='remove-filter'){if(v==='family')family='all';if(v==='note')noteFilter='';if(v==='query')query='';return true;}
 if(a==='compare'&&compared.has(Number(v)))comparisonCandidate=null;
 if(a==='compare'&&!compared.has(Number(v))&&compared.size===2){comparisonCandidate=Number(v);say('Choose one perfume to replace.');return true;}
 if(a==='replace-comparison'&&comparisonCandidate!==null){compared.delete(Number(v));compared.add(comparisonCandidate);comparisonCandidate=null;say('Comparison updated.');return true;}
 if(a==='cancel-comparison'){comparisonCandidate=null;return true;}
 if(a==='clear-compare')comparisonCandidate=null;
 if(a==='hw-publish'&&v==='0'&&!hwPublish[0]&&!editorialChecks.every(Boolean)){say('Acknowledge all three review requirements first.');return true;}
 return false;
}
function bindDepthForms(){
 const f=root.querySelector('#correction-form');
 if(f)f.addEventListener('submit',e=>{e.preventDefault();const reason=String(new FormData(f).get('reason')||'').trim();if(!reason){fieldError(f,['reason'],'correction-error','Explain the correction before changing this record.');return;}const i=correction.student;attendanceAudit.push({student:i,from:roster[i],to:correction.to,by:'Faculty correction',reason});roster[i]=correction.to;correction=null;go('audit');say('Correction saved with its reason. The shared record is updated.');});
}

function render(){const allowed={holland:['paper','discover','builder','detail','walk','story','complete','tools','cms','stops','archive'],imhere:['faculty','course','reviews','student','history','directory','student-detail','excuse','verification','audit','correction'],loopline:['dashboard','create','schedule','confirmed','tracking'],nutriva:['paper','tonight','recipe','pantry','plan','grocery','inventory-review','saved','cook'],novella:['paper','discover','book','reader','library','desk','blind','passages'],aurea:['paper','discover','notes','detail','finder','results','compare','archive','journal','evolution','sampling']};if(!allowed[app].includes(view))view=config.nav[0][0];purposeFrame(depthContent(refinedContent(purposeContent(identityContent(({holland,imhere,loopline,nutriva,novella,aurea})[app]())))));bindForms();bindDepthForms();refineCurrentInterface();}

function identityAction(a,v){
 if(a==='hw-filter'){hwTourFilter=v;return true;}
 if(a==='hw-publish'){hwPublish[Number(v)]=!hwPublish[Number(v)];say(hwPublish[Number(v)]?'Sample route marked ready for review. Nothing published.':'Sample route returned to draft.');return true;}
 if(a==='hw-story'){activeStops=[0,1,2];walkStep=Number(v);finished=false;view='story';return true;}
 if(a==='student-detail'){selectedStudent=Number(v);view='student-detail';return true;}
 if(a==='transit-next'){transitStep=transitStep===3?0:transitStep+1;say('Sample journey advanced. No real pickup status changed.');return true;}
 if(a==='transit-back'){transitStep=Math.max(0,transitStep-1);return true;}
 if(a==='meal-filter'){mealFilter=v;return true;}
 if(a==='save-meal'){savedMeals.has(v)?savedMeals.delete(v):savedMeals.add(v);say(savedMeals.has(v)?'Saved to your recipe box.':'Removed from your recipe box.');return true;}
 if(a==='confirm-ingredient'){const it=reviewItems[Number(v)];it.confirmed=true;pantry.add(it.name);say(it.name+' confirmed. Meal matches and groceries updated.');return true;}
 if(a==='skip-ingredient'){reviewItems.splice(Number(v),1);say('Suggestion skipped. Pantry unchanged.');return true;}
 if(a==='start-cook'){cookStep=0;cookFinished=false;view='cook';return true;}
 if(a==='cook-next'){if(cookStep===2)cookFinished=true;else cookStep++;return true;}
 if(a==='cook-back'){cookStep=Math.max(0,cookStep-1);return true;}
 if(a==='reset-books'){bookGenre='all';mood='all';return true;}
 if(a==='shelf-filter'){shelfFilter=v;return true;}
 return false;
}

function bindForms(){const excuse=document.querySelector('#excuse-form');if(excuse)excuse.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(excuse),context=String(data.get('context')||'').trim();if(!context){fieldError(excuse,['context'],'excuse-error','Add a brief explanation before submitting.');return;}reviewReasons[0]=String(data.get('reason'))+': '+context;attendanceAudit.push({student:0,from:roster[0],to:'Needs review',by:'Student review request',reason:reviewReasons[0]});roster[0]='Needs review';go('student');say('Sample review submitted. No message was sent.');});const handoff=document.querySelector('#handoff-form');if(handoff)handoff.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(handoff);if(formStep===0){eligible=data.get('eligible');if(eligible!=='yes'){fieldError(handoff,['eligible'],'form-error','Pause here and confirm eligibility with your organization before continuing.');return;}}if(formStep===1){food=String(data.get('food')||'').trim();quantity=String(data.get('quantity')||'');if(!food||!Number.isInteger(Number(quantity))||Number(quantity)<1||Number(quantity)>500){fieldError(handoff,[!food?'food':'quantity'],'form-error','Add a food description and a whole number from 1 to 500.');return;}}if(formStep===2)windowChoice=String(data.get('window'));if(formStep===3){confirmed=true;record={food,quantity,windowChoice};if(handoffEditing){handoffRevision++;handoffEditing=false;}else{recordCount++;handoffRevision=1;}go('confirmed');say('Sample handoff created. No pickup has been booked.');}else{formStep++;render();}});
const p=document.querySelector('#pantry-form');if(p)p.addEventListener('submit',e=>{e.preventDefault();const value=new FormData(p).get('ingredient');if(pantry.has(value)){say(value+' is already in your pantry.');return;}pantry.add(value);render();say(value+' added. Meal matches and grocery list updated.');});
const j=document.querySelector('#journal-form');if(j)j.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(j),text=String(data.get('note')||'').trim();if(!text){fieldError(j,['note'],'journal-error','Add an impression before saving.');return;}journal.push({scent:Number(data.get('scent')),text});go('archive');say('Wear note saved for this visit.');});
const search=document.querySelector('#scent-search');if(search)search.addEventListener('input',e=>{if(e.isComposing)return;query=e.target.value.toLowerCase();const cursor=e.target.selectionStart;render();const next=document.querySelector('#scent-search');next.focus();try{next.setSelectionRange(cursor,cursor);}catch{}clearTimeout(searchAnnouncement);searchAnnouncement=setTimeout(()=>{if(view==='discover')say(root.querySelectorAll('.au-index-card').length+' perfumes found.');},250);});
}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.view){go(b.dataset.view);return;}const action=b.dataset.action;if(!action)return;const [a,...rest]=action.split(':'),v=rest.join(':');let rerender=true;const previousView=view;if(a==='print-paper'){if(typeof window.print==='function')window.print();else say('Use your browser’s Print command to save or print this sheet.');return;}if(depthAction(a,v)||refinedAction(a,v)||purposeAction(a,v)||identityAction(a,v)){render();if(view!==previousView){window.scrollTo({top:0,behavior:'instant'});const h=root.querySelector('h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}}else{restoreActionFocus(action);}return;}
if(a==='view'){go(v);return;}if(a==='walks'){document.querySelector('#walks')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}
if(a==='tour'){tour=Number(v);finished=false;customWalk=false;activeStops=[0,1,2];go('detail');return;}if(a==='preview-custom'){if(!chosenStops.size)return;activeStops=[...chosenStops].sort();customWalk=true;walkStep=0;finished=false;go('detail');return;}if(a==='start-walk'){walkStep=0;finished=false;paused=false;go('walk');return;}if(a==='pause')paused=!paused;if(a==='next-stop'){if(paused)return;if(walkStep===activeStops.length-1){finished=true;go('complete');return;}walkStep++;}if(a==='reset-walk'){finished=false;walkStep=0;go('discover');return;}
if(a==='session'){sessionOpen=!sessionOpen;say('Sample session '+(sessionOpen?'opened.':'closed.'));}if(a==='check-in'&&sessionOpen){attendanceAudit.push({student:0,from:roster[0],to:'Present',by:'Student check-in'});roster[0]='Present';say('Sample attendance confirmed. Faculty record updated.');}if(a==='request-review'){roster[0]='Needs review';say('Sample review requested. No message was sent.');}if(a==='approve'||a==='absent'){attendanceAudit.push({student:Number(v),from:roster[Number(v)],to:a==='approve'?'Present':'Absent',by:'Faculty review'});roster[Number(v)]=a==='approve'?'Present':'Absent';say('Sample attendance corrected.');}
if(a==='new-handoff'){formStep=0;food='';quantity='12';eligible='';go('create');return;}if(a==='form-back'){const form=document.querySelector('#handoff-form');const data=new FormData(form);if(formStep===1){food=String(data.get('food')||'');quantity=String(data.get('quantity')||'');}if(formStep===2)windowChoice=String(data.get('window'));formStep=Math.max(0,formStep-1);}
if(a==='meal'){mealIndex=Number(v);go('recipe');return;}if(a==='plan'){plan.has(v)?plan.delete(v):plan.add(v);say(plan.has(v)?'Meal planned. Grocery list updated.':'Meal removed. Grocery list updated.');}if(a==='remove-ingredient'){pantry.delete(v);say('Ingredient removed. Meal matches updated.');}
if(a==='book'){bookIndex=Number(v);go('book');return;}if(a==='save-book'){const i=Number(v);savedBooks.has(i)?savedBooks.delete(i):savedBooks.add(i);say(savedBooks.has(i)?'Saved to your library.':'Removed from your library.');}if(a==='mood')mood=v;if(a==='night')night=!night;if(a==='text-smaller')readingSize=Math.max(18,readingSize-2);if(a==='text-larger')readingSize=Math.min(30,readingSize+2);
if(a==='scent'){scentIndex=Number(v);go('detail');return;}if(a==='save-scent'){const i=Number(v);savedScents.has(i)?savedScents.delete(i):savedScents.add(i);say(savedScents.has(i)?'Saved to your archive.':'Removed from your archive.');}if(a==='compare'){const i=Number(v);if(compared.has(i))compared.delete(i);else if(compared.size<2)compared.add(i);else{say('Compare two at a time. Remove one selection first.');return;}say(compared.size+' fragrance'+(compared.size===1?'':'s')+' selected.');}if(a==='family')family=v;if(a==='preference')preference=v;if(a==='clear-scents'){family='all';query='';}
if(rerender){render();restoreActionFocus(action);}
});
