function restoreActionFocus(action){
 const next=[...root.querySelectorAll('[data-action]')].find(x=>x.dataset.action===action)||root.querySelector('[data-action^="undo-"]')||root.querySelector('h1');
 if(next){if(next.tagName==='H1')next.tabIndex=-1;next.focus({preventScroll:true});}
}
function fieldError(form,fields,id,message){
 const note=form.querySelector('#'+id);if(note)note.textContent=message;
 fields.forEach(name=>form.querySelectorAll('[name="'+name+'"]').forEach(el=>{
  el.setAttribute('aria-invalid','true');const ids=new Set((el.getAttribute('aria-describedby')||'').split(' ').filter(Boolean));ids.add(id);el.setAttribute('aria-describedby',[...ids].join(' '));
 }));
 form.querySelector('[name="'+fields[0]+'"]')?.focus();
}
function paperContent(){
 let inside='',backView='discover',heading='',help='';
 if(app==='aurea'){
  backView='compare';heading='The sampling field sheet';help='Two profiles, the same questions. Add your own observations after trying a sample.';
  const selection=[...compared];
  inside=selection.length?`<div class="paper-masthead"><span>áurea</span><span>THE PERFUME INDEX<br>PERSONAL SAMPLING SHEET</span></div><h2>Compare the notes.<br><em>Keep your impression.</em></h2><p class="paper-intro">Fragrance notes describe character. Your experience is personal.</p><div class="paper-scent-grid">${selection.map(i=>`<section><span class="paper-code">A—00${i+1} / ${E(scents[i].tag)}</span><h3>${E(scents[i].name)}</h3>${scents[i].notes.map((n,j)=>`<div class="paper-note-row"><strong>${['Opening','Heart','Base'][j]}</strong><p>${E(n)}</p></div>`).join('')}<h4>After sampling</h4><div class="writing-space">First impression</div><div class="writing-space">Later in the day</div><div class="writing-space">Would I sample it again? Why?</div></section>`).join('')}</div><p class="paper-footnote">Original illustrative fragrance profiles. This is a personal observation sheet, not an ingredient, allergy, safety or wear-performance statement.</p>`:'';
 }else if(app==='holland'){
  backView='detail';heading='A little guide to keep';help='A readable companion for the stories you chose. It gives you somewhere to pause and write.';
  inside=`<div class="paper-masthead"><span>Holland</span><span>MICHIGAN<br>AT YOUR OWN PACE</span></div><h2>Look closer.<br>Take your time.</h2><p class="paper-intro">${activeStops.length} selected observation prompts. Keep the order; choose your own pace.</p><ol class="paper-holland-list">${activeStops.map((i,n)=>`<li><span>${String(n+1).padStart(2,'0')}</span><div><h3>${E(stops[i])}</h3><p>${['Notice a detail that makes this place feel welcoming.','Look for a sign of how the street has changed.','Choose a material, a letterform or a small detail to remember.'][i]}</p><div class="writing-space">Something I noticed</div></div></li>`).join('')}</ol><div class="paper-help"><h3>Before you go</h3><p>Check local information for an actual route, current access, places to rest and return transport. Pause whenever you need.</p></div><p class="paper-footnote">Concept observation prompts, not verified historical stops or walking directions. This page does not replace a map or current local guidance.</p>`;
 }else if(app==='nutriva'){
  backView='grocery';heading='Your list, off screen';help='The same missing ingredients, with the meals that explain why they are here.';
  const list=grocery();
  inside=plan.size?`<div class="paper-masthead"><span>nutriva</span><span>THE EVERYDAY KITCHEN<br>SHOPPING WORKSHEET</span></div><h2>Check at home.<br>Take what’s missing.</h2><div class="paper-meals"><strong>For the plan</strong><p>${meals.filter(m=>plan.has(m.id)).map(m=>E(m.name)).join(' · ')}</p></div>${list.length?`<ul class="paper-grocery">${list.map(name=>`<li><span class="paper-box" aria-hidden="true">${checked.has(name)?'✓':''}</span><div><h3>${E(name)}${checked.has(name)?' <small>Already checked</small>':''}</h3><p>For ${meals.filter(m=>plan.has(m.id)&&m.ingredients.includes(name)).map(m=>E(m.name)).join(' + ')}</p></div></li>`).join('')}</ul>`:'<p class="paper-all-set">All listed ingredients are in your sample pantry. Check quantities before shopping.</p>'}<div class="writing-space">Anything else to pick up?</div><p class="paper-footnote">Generated from this visit’s sample plan and pantry. Ingredient names only; check quantities, freshness and dietary needs against a complete recipe.</p>`:'';
 }else if(app==='novella'){
  backView='passages';heading='A few words to return to';help='The passages you kept, with each title still attached. An original-text reading keepsake.';
  inside=passages.length?`<div class="paper-masthead"><span>novella.</span><span>THE PERSONAL EDIT<br>WORDS WORTH KEEPING</span></div><h2>A passage.<br><em>A place to return.</em></h2><div class="paper-passages">${passages.map((i,n)=>`<section><span class="paper-code">${String(n+1).padStart(2,'0')} / OPENING PASSAGE</span><blockquote>${E(books[i].text)}</blockquote><h3>${E(books[i].title)}</h3><div class="writing-space">Why I kept this</div></section>`).join('')}</div><p class="paper-footnote">Original fiction written for this portfolio concept. Source titles remain attached; no full published book or licensed excerpt is represented.</p>`:'';
 }
 document.body.classList.add('paper-mode');
 return `${back('view:'+backView,'Back to '+({aurea:'comparison',holland:'my selected stories',nutriva:'groceries',novella:'my passages'}[app]))}<header class="print-controls"><p class="eyebrow">FROM SCREEN TO PAPER</p><h1>${heading}</h1><p>${help}</p>${inside?`${B('Print this sheet','print-paper')}<p class="meta">A4 layout. Use 100% scale and turn off browser headers and footers. Review the preview before printing.</p>`:`<div class="notice"><p>${app==='aurea'?'Choose one or two perfumes to make a comparison sheet.':app==='novella'?'Save a passage in the reading room before making your keepsake.':'Add a meal to your plan before making a shopping sheet.'}</p>${B('Return and choose','view:'+backView,true)}</div>`}</header>${inside?`<article class="paper-sheet paper-${app}" aria-label="Printable ${config.name} design">${inside}</article>`:''}`;
}
