 forms.forEach(form=>{
  const error=form.querySelector('[role="alert"]');
  if(error)form.querySelectorAll('input,select,textarea').forEach(el=>{
   const ids=new Set((el.getAttribute('aria-describedby')||'').split(' ').filter(Boolean));ids.add(error.id);el.setAttribute('aria-describedby',[...ids].join(' '));
  });
 });
 const places={aurea:{view:'compare',label:'Make a sampling sheet'},holland:{view:'detail',label:'Take a paper copy'},nutriva:{view:'grocery',label:'Make a shopping sheet'},novella:{view:'passages',label:'Make a reading keepsake'}};
